      "翠影女王": "Королева теней Изумруда",
      "王庭的盗贼女王": "Королева воров королевского двора",
      "统御整个哥布林王庭的盗贼女王，每个行动回合都会呼来两名普通哥布林。": "Королева воров, правящая всем гоблинским двором; на каждый ход действия она призывает двух обычных гоблинов.",
      "无尽绿潮": "Бесконечный зелёный прилив",
      "每个敌方行动回合，在空位免费召唤2个普通哥布林。": "На каждый ход действия врага вызвать 2 обычных гоблинов в пустые слоты бесплатно.",
      "丰穗战母·布蕾娅": "Мать войны урожая Бреия",
      "金麦农场的熊族统领": "Вождь медведей Золотой пшеничной фермы",
      "守护熊族新家园的战母。每回合召唤丰穗近卫，每3回合强化场上全部熊族。": "Мать войны, защищающая новый дом медведей. Вызывает стража урожая каждый ход, и каждые 3 хода усиливает всех медведей на поле.",
      "护田战令": "Указ стража поля",
      "每个敌方行动回合召唤1个5攻/7血的丰穗近卫。": "На каждый ход действия врага вызвать 5/7 стража урожая.",
      "丰收之怒": "Гнев урожая",
      "每3个敌方行动回合，使场上所有熊族随从获得+1/+2。": "Каждые 3 хода действия врага дать всем медведям на поле +1/+2.",
      "碧露大贤者·涅芙莉": "Великая мудрец Нефрия Голубой росы",
      "梦幻森林的史莱姆引路者": "Проводница слизи в лесу снов",
      "拒绝离开故土的大贤者。每个行动回合恢复首领和全部史莱姆生命，每3回合分裂出两名碧露近卫。": "Великая мудрец, отказывающаяся покидать свою родину. На каждый ход действия она исцеляет себя и всю слизь, и каждые 3 хода отделяет двух стражей Голубой росы.",
      "不灭胶质": "Бессмертная слизь",
      "每个敌方行动回合，为首领恢复10点生命，并为所有史莱姆随从恢复5点生命。": "На каждый ход действия врага восстановить 10 Здоровья босу и 5 Здоровья всем существам-слизям.",
      "碧露分裂": "Разделение Голубой росы",
      "每3个敌方行动回合，免费召唤2个4攻/12血碧露近卫。": "Каждые 3 хода действия врага вызвать 2 стража Голубой росы 4/12 бесплатно.",
      "森林狼王": "Король лесных волков",
      "裂月之牙": "Клык разорванной луны",
      "每3回合召唤幼狼；每4回合发动狼王咆哮。": "Вызывает щенка волка каждые 3 хода; выпускает вой Короля волков каждые 4 хода.",
      "狼王号令": "Команда Короля волков",
      "每3个敌方回合，在空位免费召唤1只幼狼。": "Каждые 3 хода врага вызвать 1 щенка волка в пустой слот бесплатно.",
      "裂月咆哮": "Вой разорванной луны",
      "每4个敌方回合，使所有狼类随从永久获得+1攻击。": "Каждые 4 хода врага все волки навсегда получают +1 Атаку.",
      "银灰狼女猎手": "Охотница серебристо-серого волка",
      "千枝城的灰牙首领": "Лидер серого клыка Города Тысячи Ветвей",
      "避开翡翠城追兵、占据千枝城废墟的狼族首领。每回合都会呼唤一只迅猛的灰狼投入战斗。": "Вождь волков, который избежал преследования Изумрудного города и захватил развалины Города Тысячи Ветвей. Каждый ход она призывает быстрого серого волка в бой.",
      "灰狼增援": "Подкрепления серого волка",
      "每个敌方行动回合，召唤1只4攻/1血、可立即攻击随从的突击灰狼。": "На каждый ход действия врага вызвать 4/1 штурмового серого волка, который может сразу атаковать существа.",
      "千枝城魔族军官团": "Корпус демонических офицеров Тысячи Ветвей",
      "拒绝退避的重建者": "Перестройщики, отказывающиеся отступать",
      "第五关剧情结束后驻扎于千枝城的魔族据点。随从均为20攻/200血，属于长期挑战内容。": "Демоническая крепость, расположенная в Городе Тысячи Ветвей после истории Главы 5. Все существа имеют 20/200 — долгосрочный контент вызовов.",
