      "每个敌方行动回合，召唤1个2攻/2血的普通哥布林。": "На каждый боевой ход врага призовите обычного гоблина 2/2.",
      "守卫金麦农场的新住民，擅长以高生命熊族随从稳固战线。": "Новые жители охраняют Золотую ферму зерна, умеют держать линию своими высокозащитными медведями-существами.",
      "农垦本能": "Инстинкт фермера",
      "每2个敌方行动回合召唤1个会随进度成长的巡田熊民。": "На каждые 2 боевых хода врага призовите Медведя Полевого патруля, который растёт с прогрессом.",
      "女王之血唤醒的史莱姆，以厚重生命、分裂与持续再生缓慢推进战线。": "Слизи, пробуждённые кровью Королевы, медленно продвигают линию вперёд с толстым Здоровьем, раздваиваются и постоянно регенерируют.",
