      "每个敌方行动回合，为首领和全部史莱姆随从恢复生命。": "На каждый боевой ход врага восстановите Здоровье боссу и всем существам-слизям.",
      "喝下女王之血后开智的灰狼与野兽，攻击迅猛但防御薄弱，许多单位登场便会扑击。": "Серые волки и звери, пробуждённые после питья крови Королевы. Свирепы в атаке, но слабы в защите; многие прыгают, как только входят.",
