      "今天我代表的不是归顺，而是一个异族也能公开竞争、堂堂正正赢得掌声的王国。": "Сегодня я представляю не покорность, но королевство, где другие расы могут соревноваться открыто и выиграть честные аплодисменты.",
      "漂亮。能把我逼到这里，说明王都接纳的也确实是一位值得尊敬的对手。": "Прекрасно. То, что ты толкнул меня так далеко, доказывает, что столица действительно приветствует противника, достойного уважения.",
      "我不会替那些偏见证明异族只配躲在荒野。来，最后一轮！": "Я не буду доказывать правоту тех предубеждений, что другие расы должны оставаться скрытыми в дикой природе. Давай — финальный раунд!",
      "你赢了。愿这座竞技场继续证明：人类与异族可以争胜，却不必彼此仇恨。": "Ты выиграл. Пусть эта арена продолжает доказывать: люди и другие расы могут соревноваться без ненависти друг к другу.",
      "出牌再快一点。观众买票不是来看你思考人生的。": "Играй быстрее. Публика не покупала билеты, чтобы смотреть, как ты размышляешь о жизни.",
      "你管这叫战线？我家的晾衣绳都比它更难突破。": "Это то, что ты называешь боевой линией? Моя верёвка для стирки твёрже.",
      "放心，我会给你留点体面——至少等裁判宣布以后再笑。": "Расслабься, я оставлю тебе достоинство — я хотя бы дожду сигнала рефери, перед тем как засмеяться.",
      "别看记分牌了，它不会因为你盯得够久就站到你那边。": "Прекрати смотреть на табло. Оно не переключится, только потому что ты на него смотришь.",
      "刚才那一下还算像样。不过想让我闭嘴，你还差最后一段路。": "Тот последний ход был неплох. Но чтобы заставить меня молчать, у тебя ещё есть один последний отрезок.",
      "别急着向观众挥手！我只是把翻盘留到最吵的时候。": "Не машите публике! Я только сохраняю свой камбэк на самый громкий момент.",
      "今天算你赢。下次我会先击败你，再投诉这块明显偏向你的地板。": "Ты выиграл сегодня. В следующий раз я тебя побью первым, потом подам жалобу на этот пол, который явно тебе благоволит.",
      "别介意，我正在记录你的出牌习惯。真正危险的数据，往往来自自信的人。": "Не обращай на меня внимание, я записываю твои привычки в игре. По-настоящему опасные данные часто приходят от уверенных людей.",
      "每次交换都在缩小答案范围。再过几轮，你的选择就会只剩一种。": "Каждая торговля сужает ответ. Ещё несколько раундов и у тебя останется только один выбор.",
      "竞技场比实验室诚实：错误的理论会当场掉血。": "Арена честнее лаборатории: неверные теории теряют Здоровье на месте.",
      "放心，若你击败我，我会如实把结论写进报告。": "Будь уверен, если ты победишь меня, я напишу вывод в мой отчёт честно.",
      "数据偏离预测了。很好，没有意外的研究才最无聊。": "Данные отклоняются от предсказания. Хорошо — исследование без сюрпризов — самое скучное.",
      "样本正在反过来验证研究者……我承认这个结果很有说服力。": "Образец проверяет исследователя... Я признаю, этот результат очень убедительный.",
      "结论成立：你的临场判断胜过我的模型。下一版论文会写上这一条。": "Вывод подтверждён: твоё мгновенное суждение бьёт мою модель. Следующий черновик моей статьи будет это говорить.",
      "竞技场没有真正的仇敌，只有愿意把本领摆到阳光下的人。": "В арене нет истинных врагов, только люди, готовые показать свои навыки под солнцем.",
      "别为保存生命而放弃阵线。荣誉来自承担风险，不是躲过风险。": "Не покидай линию, чтобы спасти жизнь. Честь идёт из рисков, не из их избежания.",
      "观众记得胜负，战士应当记得自己在压力下做过什么选择。": "Публика помнит результат; воин должен помнить выборы, сделанные под давлением.",
      "无需留手。尊重对手最好的方式，就是拿出真正想赢的力量。": "Не сдерживайся. Лучший способ уважить противника — принести силу, которая действительно хочет выиграть.",
      "好一记正面突破。疼痛会过去，失去判断才是真正的败势。": "Отличное лобовое прорывание. Боль проходит; потеря суждения — вот истинное поражение.",
      "只剩最后一点生命，正好用来检验最后一点意志。": "Всего одна последняя точка Здоровья — идеально для проверки последнего кусочка воли.",
      "胜负已定。我记住了你的战术，也会把掌声留给配得上它的人。": "Поединок решён. Я запомнил твою тактику и сохраню мои аплодисменты для тех, кто их заслуживает.",
      "并": "и",
      "，它们可以立即攻击": ", и они могут атаковать сразу же",
