      "点击手牌出牌，或点击带绿色边框的友方随从发起攻击。": "Нажми на карту в руке, чтобы разыграть её, или нажми на дружественное существо с зелённой границей, чтобы атаковать.",
      "选择发光的敌方目标；若有突破路线，也可以点击敌方英雄。": "Выбери светящуюся цель врага; если линия прорвана, ты также можешь нажать на героя врага.",
      "武器已举起：选择敌方随从；若有突破路线，也可以攻击敌方英雄。": "Оружие поднято: выбери существо врага; если линия прорвана, ты также можешь атаковать героя врага.",
