      "曾任王都护卫队长。野兽接连觉醒后，他认为只守住一座王都远远不够，于是离开王都、集结自己的小队，奔赴各地平定乱局。": "Некогда капитан королевской стражи столицы. Когда звери начали пробуждаться один за другим, он решил, что охранять одну лишь столицу недостаточно: покинул её, собрал собственный отряд и отправился усмирять смуту по всей земле.",
