      "（已拥有）": "(уже есть)",
      "已加入英雄技能收藏，可在英雄档案装备。": "Добавлено в вашу коллекцию навыков героя; экипируйте это в профиле героя.",
      "，你成为本届王冠杯冠军！": ", вы чемпион Кубка Короны этого года!",
