      "{0}已被第五名军官带走。四名10攻/200血军官封锁前排，并将在{1}回合后撤离。": "{0} был унесён пятым офицером. Четыре офицера 10/200 запечатывают передний ряд и отступят в {1} ходов.",
      "你的回合 · 第{0}回合": "Ваш ход · Ход {0}",
      "{0}的回合": "Ход {0}",
      "法力每回合恢复至 {0}/{1}，不会自动增长。": "Мана восстанавливается до {0}/{1} каждый ход и не растёт автоматически.",
      "{0} {1} · {2}费": "{0} {1} · {2} мана",
      "Lv{0} · 固定法力上限": "Lv{0} · Фиксированный предел маны",
      "牌库 {0} · 手牌 {1}/10": "Колода {0} · Рука {1}/10",
      "剩余{0}张": "{0} осталось",
      "经验 {0}": "Опыт {0}",
      "{0}第{1}关 · 已完成{2}节点": "{0} Глава {1} · {2} узлов очищено",
      "救治全部{0}名伤员": "Исцелить все {0} раненых",
      "· 英雄生命 {0}/{1}，同时恢复满生命": "· Здоровье героя {0}/{1}, также полностью восстановлено",
      "每回合恢复至 {0}/{1}。永久上限不封顶，只能由统领试炼首次通关提升。": "Восстанавливается до {0}/{1} каждый ход. Постоянный лимит не имеет границ и может быть поднят только первыми очищениями Испытаний командира.",
      "{0} 场胜利 · {1} 次通关 · 收藏 {2} 张": "{0} побед · {1} очищений · {2} карты собраны",
