      "已救治{0}名伤员": "Исцелено {0} раненых",
      "{0} 每回合可使用一次，消耗{1}点法力。": "{0} Используется один раз за ход, стоит {1} маны.",
      "技能经验 {0}": "Навык опыта {0}",
      "当前已达到第{0}关等级上限 Lv{1}。": "Достигнут лимит уровня Главы {0} Lv{1}.",
      "距离 Lv{0} 还需 {1} 经验": "{1} опыта до Lv{0}",
