      "森灵德鲁伊": "Друид рощи",
      "林海边境最年轻的神射手，她的箭能穿过层层枝叶，找到藏在阵后的敌人。": "Самая юная снайперша лесного пограничья: её стрелы проходят сквозь ветви и находят врагов, укрывшихся за строем.",
      "离开法塔独自研究裂隙的魔女，擅长把魔力拆成无数枚难以躲避的飞弹。": "Ведьма, покинувшая башню магов ради изучения Разлома; умеет дробить ману на бесчисленные снаряды, от которых трудно увернуться.",
      "太阳神殿派往前线的圣女，相信每一名士兵都值得再站起来一次。": "Святая, посланная на фронт Храмом Солнца: она верит, что каждый солдат заслуживает подняться ещё раз.",
      "北地部族的蛮王，以自己的鲜血点燃战士的怒火。": "Вождь северных племён, разжигающий ярость воинов собственной кровью.",
      "月林巡林员的首领，总能让敌人在树影里看到不该出现的弓手。": "Глава следопытов Лунного леса: враги всегда замечают в тени лучников там, где их быть не должно.",
      "王都晨辉骑士团的老兵，他的盾阵从未在他面前后退一步。": "Ветеран столичного ордена Рассветного сияния: его стена щитов ни разу не отступила ни на шаг.",
      "古林之心孕育的德鲁伊，她种下的每一株幼苗都会长成守护森林的古树。": "Друид, рождённая сердцем древней рощи: каждый посаженный ею росток вырастает в древнее дерево-хранителя леса.",
      "穿林箭": "Пронзающая стрела",
      "奥术飞弹": "Чародейские снаряды",
      "晨曦复苏": "Рассветное возрождение",
      "血怒狂击": "Кровавое неистовство",
      "林间伏兵": "Лесная засада",
