      "萌芽古树": "Прорастающий древень",
      "无视前排保护，对任意一个敌方随从造成{0}点伤害；若击杀目标，抽1张牌。": "Игнорируя защиту первого ряда, наносит {0} урона любому вражескому существу; если оно погибает, возьмите 1 карту.",
      "发射{0}枚奥术飞弹，每枚随机对一个敌方随从或敌方英雄造成1点伤害。": "Выпускает {0} чародейских снарядов; каждый наносит 1 урон случайному вражескому существу или вражескому герою.",
      "使所有己方随从恢复至满生命，并为英雄恢复{0}点生命。": "Полностью восстанавливает здоровье всех ваших существ и восстанавливает {0} здоровья вашему герою.",
      "英雄失去2点生命，使一个己方随从本回合获得+{0}攻击，并可以立即再次攻击。": "Ваш герой теряет 2 здоровья; ваше существо получает +{0} к атаке до конца хода и может сразу атаковать снова.",
      "在后排召唤一个{0}攻/{1}血的远程林影弓手，它可以立即攻击随从。": "Призывает в задний ряд дальнобойного лучника Теневого листа {0}/{1}; он может сразу атаковать существ.",
      "所有己方前排随从永久获得+{0}生命；若前排为空，则召唤一个0攻/{1}血的圣盾卫士。": "Все ваши существа первого ряда навсегда получают +{0} к здоровью; если первый ряд пуст, призывает Стража эгиды 0/{1}.",
      "召唤一个{0}攻/{1}血的古树幼苗；它在你每回合开始时永久获得+1/+1。": "Призывает Древний росток {0}/{1}; в начале каждого вашего хода он навсегда получает +1/+1.",
