      "{0}陷入血怒，本回合攻击力提升至{1}，可以立即攻击。": "{0} впадает в кровавое неистовство: атака до конца хода — {1}, может сразу атаковать.",
      "{0}陷入血怒，本回合攻击力提升至{1}。": "{0} впадает в кровавое неистовство: атака до конца хода — {1}.",
      "圣盾壁垒加固前排：{0}个随从永久获得+{1}生命。": "Стена эгиды укрепляет первый ряд: {0} существ навсегда получают +{1} к здоровью.",
