      "新英雄「{0}」将从头开始远征。之后的进度会自动保存到所选栏位。": "Новый герой «{0}» начнёт поход с нуля. Дальнейший прогресс будет автоматически сохраняться в выбранную ячейку.",
      "读取后，之后的进度会自动保存到该栏位。": "После загрузки прогресс будет автоматически сохраняться в эту ячейку.",
