      "未解锁 · 第{0}关已结缘 {1}/{2}": "Закрыто · Глава {0}, узы {1}/{2}",
      "最终首领卡牌": "Карты финальных боссов",
      "牢房还空着。击败冒险中的首领，它们就会被押回这里。": "Камеры пока пусты. Побеждайте боссов в походах — их доставят сюда.",
      "已关押 {0}/{1} 名觉醒者。各关的最终首领不在此列：森林狼王战死于密林，其余首领都在最后关头被同族救走。": "В заключении {0}/{1} Пробуждённых. Финальных боссов глав здесь нет: Лесной Король-Волк пал в чаще, а остальных в последний момент спасли сородичи.",
      "第二关起击败的首领，其首杀奖励卡要与牢里的本人结缘（好感度{0}）后才能出战；继续投喂，每{1}点好感升一级（最高{2} Lv{3}），结缘后每高一级：随从+{4}攻击、+{5}生命，法术效果提升{6}级。最终首领的卡牌要等本关全部在押首领结缘才能使用，等级取其中最低的一位。每名首领每天（现实{7}分钟）只能投喂一次，距离新的一天还有{8}。背包里共有 {9} 份食物。": "Начиная со 2-й главы, карту за первую победу над боссом можно использовать только после установления уз с ним в тюрьме (симпатия {0}). Продолжайте кормить: каждые {1} симпатии дают уровень (максимум {2} ур.{3}). Каждый уровень выше «Уз» даёт существам +{4} к атаке и +{5} к здоровью, а заклинаниям +{6} уровня эффекта. Карта финального босса открывается, когда узы установлены со всеми пленными боссами главы, и берёт наименьший из их уровней. Каждого босса можно кормить раз в день ({7} реальных минут); новый день наступит через {8}. В рюкзаке {9} ед. еды.",
      "📖 族群往事": "📖 Предания народов",
      "前往城镇商店": "В городские лавки",
      "返回队伍营地": "Вернуться в лагерь отряда",
