      "{0} 结缘Lv1：{1}；誓约Lv5：{2}": "{0} Узы ур.1: {1}; Клятва ур.5: {2}",
      "派遣劳动": "Работы",
      "结缘后的首领每天可以派出去干一次活，{0}小时（现实{1}分钟）后带着收获回营；干活期间不能投喂。可派 {2} 名 · 在外 {3} 名": "Боссов, с которыми установлены узы, можно раз в день отправлять на работу; через {0} ч ({1} реальных минут) они возвращаются с добычей. Пока они на работе, кормить их нельзя. Доступно: {2} · На работе: {3}",
