      "它还不愿意对你说起过去。": "Пока не хочет рассказывать о своём прошлом.",
      "🔒 第{0}关在押首领的好感等级总和达到{1}后解锁（当前{2}）。": "🔒 Откроется, когда сумма уровней уз пленных боссов главы {0} достигнет {1} (сейчас {2}).",
      "营地监狱 · 好感剧情": "Лагерная тюрьма · Истории уз",
      "与同一关的在押首领结下的好感越深（全部首领的好感等级加在一起），它们就越愿意讲出本族的往事。每名首领到{0} Lv{1}时，还会讲出自己的故事。": "Чем крепче ваши узы с пленными боссами одной главы (сумма уровней всех боссов), тем больше они расскажут о прошлом своего народа. Каждый босс также расскажет свою историю на уровне «{0}» ур.{1}.",
