      "住一晚 · {0}金币": "Переночевать · {0} золота",
      "一觉睡到第{0}天早上6:00。可以避开今晚监狱里的夜间事件（已经发生、还没处理的除外）。和自然过一天一样：队伍吃掉{1}场战斗的口粮（{2}份，现有{3}份），每名在押首领又可以投喂一次。": "Проспать до 6:00 дня {0} и избежать сегодняшнего ночного события в тюрьме (кроме уже случившегося и нерешённого). Как в обычный день, отряд съест пайки на {1} боя ({2}; есть {3}), и каждого пленного босса снова можно будет покормить.",
