      "进度已保存": "Прогресс сохранён",
      "浏览器不允许网页自己关闭标签页，请直接关闭这个窗口或标签页。下次打开游戏即可从开始界面继续。": "Браузер не позволяет странице закрыть свою вкладку. Закройте это окно или вкладку сами. В следующий раз вы сможете продолжить с титульного экрана.",
      "结束游戏": "Выйти из игры",
